3',1011);
INSERT INTO `pages` (`id`,`document_id`,`page_number`,`text`,`character_count`) VALUES (4,1,4,'Tatýana Tekinskaýanyň çagalygyny ýatlajak bolup, oňa kän seredip oturdym. Ine, birdenem şol suratdaky teke gyzjagazy bilen hyýalymda gürleşenimem duýman galypdyryn. Bu näbelli gyzjagazdan men soraýaryn, olam jogap berýär: «Sen kim, gyzjagaz?» «Bilemok...» «Seň adyň näme?» «Bilemok...» «Adyňam bileňokmy?» «Ýok...» «Kimiň gyzy? Ejeň-kakaň kim?» «Bilemok... Men hiç zat bilemog-a...» «Nirede ýaşadyň sen?» «Hanha, ho-o taýda...» «Kimler diýýärdiler size?» «Tekeler...» «Kimler?» «Tekeler biz… Düşüneňokmy, te-ke-ler...» «Sen onda teke gyzy-da, şeýle dälmi?»

